// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amount, bool targetAccepts) public {
        amount = bound(amount, 0, 1 ether);

        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        vm.assume(caller != address(0));

        vm.deal(address(c), 1 ether);

        address target;
        if (targetAccepts) {
            AcceptingReceiver ar = new AcceptingReceiver();
            target = address(ar);
        } else {
            RevertingReceiver rr = new RevertingReceiver();
            target = address(rr);
        }

        uint256 before = address(c).balance;

        vm.prank(caller);
        try c.sendMoney(target, amount, "") {
        } catch {
        }

        assertTrue(address(c).balance == before);
    }
}

contract AcceptingReceiver {
    receive() external payable {}
}

contract RevertingReceiver {
    receive() external payable { revert("nope"); }
}
